for name in unpaid_shares:
    matches=[c for c in all_coworkers if c.get('first_name')==name]
    name_to_contacts[name]=matches
    print(name,'matches',len(matches),[(m.get('first_name'),m.get('last_name'),m.get('email')) for m in matches])

# build email map; ensure exactly 1 match
email_map={}
for name,matches in name_to_contacts.items():
    if len(matches)==0:
        email_map[name]=None
    elif len(matches)==1:
        email_map[name]=matches[0]['email']
    else:
        # if multiple, choose first alphabetically by last_name
        matches_sorted=sorted(matches, key=lambda x:(x.get('last_name',''), x.get('email','')))
        email_map[name]=matches_sorted[0]['email']

print('email_map', email_map)

